/*
 * A041968  Numerators of continued fraction convergents to sqrt(507).
 * https://oeis.org/A041968
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy, less
 * Formula:   a(n) = numerator of the n-th convergent of sqrt(507) continued
 *            fraction
 * Range:     u8 n <= 2, u16 n <= 7, u32 n <= 14, u64 n <= 32, u128 n <= 65,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence elements are generated by the recurrence
   p_{-2} = 0, p_{-1} = 1,
   p_n   = a_n * p_{n-1} + p_{n-2},
   where a_n are the partial quotients of sqrt(507). */
/* The function is memoized so any order of calls is supported. */

#include <stdlib.h>
#include <stdint.h> /* in case needed for uint64_t */

static seq_t *p_cache     = NULL; /* memoized numerators */
static size_t cache_cap   = 0;
static idx_t  max_index   = (idx_t)(-1); /* no terms cached yet */

/* Continued fraction parameters for sqrt(507) */
static unsigned long long m_cf   = 0;   /* m_k */
static unsigned long long d_cf   = 1;   /* d_k */
static unsigned long long a_cf   = 22;  /* a_k, start with floor(sqrt(507)) */
static const unsigned long long a0   = 22;
static const unsigned long long D     = 507; /* the radicand */

/* Previous two convergents used while extending the cache */
static seq_t prev_prev = 1; /* p_{-1} */
static seq_t prev     = (seq_t)0; /* will be set to p_0 in init() */

/* Forward declaration of helper to compute next partial quotient */
static inline unsigned long long next_partial_quotient(void);

static void init_cache(void)
{
    /* Allocate initial cache for at least 1 element */
    if (cache_cap == 0) {
        cache_cap = 16;
        p_cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    }
    /* p_0 = a0 = 22 */
    prev = (seq_t)a0;
    p_cache[0] = prev;
    max_index = 0;

    /* Ready to generate a_1 on demand */
    /* prev_prev = 1 is already set */
}

static inline unsigned long long next_partial_quotient(void)
{
    /* m_{k+1} = d_k * a_k - m_k */
    /* d_{k+1} = (D - m_{k+1}^2) / d_k */
    /* a_{k+1} = floor( (a0 + m_{k+1}) / d_{k+1} ) */
    unsigned long long m_next = d_cf * a_cf - m_cf;

    /* Use 128-bit arithmetic to avoid overflow of m_next*m_next */
    unsigned __int128 m_next_sq = (unsigned __int128)m_next * m_next;
    unsigned long long d_next = (unsigned long long)((D - m_next_sq) / d_cf);

    unsigned long long a_next = (a0 + m_next) / d_next;

    /* Update state for next call */
    m_cf = m_next;
    d_cf = d_next;
    a_cf = a_next;

    return a_next;
}

seq_t a(idx_t n)
{
    /* Ensure initialization */
    if (cache_cap == 0) {
        init_cache();
    }

    /* If requested index within cached range, return directly */
    if (n <= max_index) {
        return p_cache[n];
    }

    /* Extend cache up to n */
    for (idx_t i = max_index + 1; i <= n; ++i) {
        unsigned long long ai = next_partial_quotient();
        seq_t cur = (seq_t)ai * prev + prev_prev;
        /* Grow cache if necessary */
        if ((size_t)(i + 1) > cache_cap) {
            size_t new_cap = cache_cap * 2;
            if (new_cap < i + 1) new_cap = i + 1;
            seq_t *new_ptr = (seq_t *)realloc(p_cache, new_cap * sizeof(seq_t));
            if (!new_ptr) {
                /* In case of allocation failure, abort */
                abort();
            }
            p_cache = new_ptr;
            cache_cap = new_cap;
        }
        p_cache[i] = cur;
        /* shift previous two for next iteration */
        prev_prev = prev;
        prev     = cur;
    }

    max_index = n;
    return p_cache[n];
}
